<template>
  <Skeleton v-if="isLoading" class="h-3 w-20 inline-block" />
  <NuxtLink
    v-else-if="isAdmin && effectiveUserId"
    :to="{ name: 'users-id', params: { id: effectiveUserId } }"
    class="underline underline-offset-2"
  >
    {{ labelValue }}
  </NuxtLink>
  <span v-else>{{ labelValue }}</span>
</template>
<script setup lang="ts">
import { getUserShortInfo, type UserShortInfo } from '~/client';

const props = defineProps<{
  user?: UserShortInfo;
  userId?: string;
}>();

const effectiveUserId = computed(() => props.userId ?? props.user?.id);

const { data, isLoading } = useQuery({
  key: () => ['user.short-info', effectiveUserId.value ?? ''],
  query: () => getUserShortInfo({ composable: '$fetch', path: { user_id: effectiveUserId.value ?? '' } }),
  enabled: () => !!effectiveUserId.value && !props.user,
});

const labelValue = computed(() => (props.user ? username(props.user) : data.value ? username(data.value) : undefined));

const { isAdmin } = useUserRole();
</script>
